/*
 * Competitor Digest page logic. Vanilla JS, no dependencies.
 * Data comes from data/digest.js (window.DIGEST), generated by scripts/bundle.py.
 * All view state (week, filters, sample mode) lives in the URL query string.
 */
(function () {
  "use strict";

  var CATEGORIES = [
    { id: "new_product", label: "New Products" },
    { id: "competitor_summary", label: "Competitor Summary" },
    { id: "event", label: "Upcoming Events" },
    { id: "financial", label: "Financial Report" },
    { id: "strategy", label: "Strategy" }
  ];
  // Page order: New Products first, then Summary, Strategy, Events, Financial.
  var SECTIONS = [
    { id: "new_product", label: "New Products", lede: "What shipped this week. Grouped by competitor." },
    { id: "competitor_summary", label: "Competitor Summary", lede: "The week in brief, per competitor." },
    { id: "strategy", label: "Strategy", lede: "Moves and signals. Our own reading is labeled Analysis." },
    { id: "event", label: "Upcoming Events", lede: "Where they will be next. Future events only, soonest first." },
    { id: "financial", label: "Financial Report", lede: "Company-level figures only. Parent-level figures name the parent." }
  ];
  var TAG_DIMS = [
    { id: "technology", label: "Technology" },
    { id: "industry", label: "Industry" },
    { id: "application", label: "Application" }
  ];
  var DIMS = ["competitor", "category", "technology", "industry", "application"];

  var data = window.DIGEST || { competitors: [], runs: [], sample_runs: [] };
  var competitors = data.competitors || [];
  var compById = {};
  competitors.forEach(function (c) { compById[c.id] = c; });

  var params = new URLSearchParams(window.location.search);
  var sampleMode = params.get("sample") === "1";
  var runs = (sampleMode ? data.sample_runs : data.runs) || [];
  runs = runs.slice().sort(function (a, b) { return a.run_date < b.run_date ? 1 : -1; });

  var state = { week: null, filters: {} };
  DIMS.forEach(function (d) { state.filters[d] = params.getAll(d).filter(Boolean); });
  var requestedWeek = params.get("week");
  state.week = runs.some(function (r) { return r.run_date === requestedWeek; }) ? requestedWeek : (runs[0] && runs[0].run_date);

  // ------------------------------------------------------------- helpers

  function $(id) { return document.getElementById(id); }

  function el(tag, attrs, children) {
    var node = document.createElement(tag);
    if (attrs) {
      Object.keys(attrs).forEach(function (k) {
        if (attrs[k] === null || attrs[k] === undefined || attrs[k] === false) return;
        if (k === "text") node.textContent = attrs[k];
        else if (k === "className") node.className = attrs[k];
        else node.setAttribute(k, attrs[k] === true ? "" : attrs[k]);
      });
    }
    (children || []).forEach(function (c) {
      if (c === null || c === undefined) return;
      node.appendChild(typeof c === "string" ? document.createTextNode(c) : c);
    });
    return node;
  }

  function svgIcon(paths) {
    var ns = "http://www.w3.org/2000/svg";
    var svg = document.createElementNS(ns, "svg");
    svg.setAttribute("class", "icon");
    svg.setAttribute("viewBox", "0 0 24 24");
    svg.setAttribute("aria-hidden", "true");
    paths.forEach(function (d) {
      var p = document.createElementNS(ns, "path");
      p.setAttribute("d", d);
      svg.appendChild(p);
    });
    return svg;
  }

  function parseDay(s) {
    var m = /^(\d{4})-(\d{2})-(\d{2})/.exec(s || "");
    return m ? new Date(Number(m[1]), Number(m[2]) - 1, Number(m[3])) : null;
  }

  function fmtDay(s, withYear) {
    var d = parseDay(s);
    if (!d) return "";
    var opts = { month: "short", day: "numeric" };
    if (withYear !== false) opts.year = "numeric";
    return d.toLocaleDateString("en-US", opts);
  }

  function fmtUtcDay(iso) {
    // Window bounds are UTC timestamps; show their UTC calendar date.
    var d = new Date(iso);
    if (isNaN(d.getTime())) return "";
    return d.toLocaleDateString("en-US", { month: "short", day: "numeric", year: "numeric", timeZone: "UTC" });
  }

  function todayStr() {
    var d = new Date();
    function pad(n) { return (n < 10 ? "0" : "") + n; }
    return d.getFullYear() + "-" + pad(d.getMonth() + 1) + "-" + pad(d.getDate());
  }

  function compName(id) { return compById[id] ? compById[id].display_name : id; }

  function isHttp(url) { return /^https?:\/\//i.test(url || ""); }

  function primaryDate(item) {
    var dates = (item.sources || []).map(function (s) { return s.published_date || ""; }).filter(Boolean).sort();
    return dates.length ? dates[dates.length - 1] : "";
  }

  function currentRun() {
    for (var i = 0; i < runs.length; i++) if (runs[i].run_date === state.week) return runs[i];
    return null;
  }

  function activeCount() {
    return DIMS.reduce(function (n, d) { return n + state.filters[d].length; }, 0);
  }

  function matches(item) {
    var f = state.filters;
    if (f.competitor.length && f.competitor.indexOf(item.competitor) < 0) return false;
    if (f.category.length && f.category.indexOf(item.category) < 0) return false;
    for (var i = 0; i < TAG_DIMS.length; i++) {
      var dim = TAG_DIMS[i].id;
      if (!f[dim].length) continue;
      var tags = (item.tags && item.tags[dim]) || [];
      if (!tags.some(function (t) { return f[dim].indexOf(t) >= 0; })) return false;
    }
    return true;
  }

  // ------------------------------------------------------------ URL sync

  function writeUrl() {
    var q = new URLSearchParams();
    if (sampleMode) q.set("sample", "1");
    if (runs.length && state.week !== runs[0].run_date) q.set("week", state.week);
    DIMS.forEach(function (d) { state.filters[d].forEach(function (v) { q.append(d, v); }); });
    var qs = q.toString();
    var url = window.location.pathname + (qs ? "?" + qs : "") + window.location.hash;
    try {
      window.history.replaceState(null, "", url);
    } catch (e) {
      // Some browsers block history updates on file:// pages. The view still works;
      // only the shareable URL is unavailable there.
    }
  }

  // ------------------------------------------------------------- header

  function renderHeader(run) {
    $("run-bar").hidden = false;

    var select = $("week-select");
    select.textContent = "";
    runs.forEach(function (r, i) {
      var label = "Week of " + fmtDay(r.run_date) + (i === 0 ? " (latest)" : "");
      var opt = el("option", { value: r.run_date, text: label });
      if (r.run_date === state.week) opt.selected = true;
      select.appendChild(opt);
    });

    $("run-window").textContent = fmtUtcDay(run.window_start_utc) + " to " + fmtUtcDay(run.window_end_utc) + " (UTC)";

    var status = $("run-status");
    status.textContent = "";
    var partial = run.status === "partial";
    status.appendChild(el("span", { className: "status-mark" + (partial ? " status-mark--partial" : ""), "aria-hidden": "true" }));
    status.appendChild(document.createTextNode(partial ? "Partial" : "Complete"));

    var banner = $("partial-banner");
    var list = $("failure-list");
    list.textContent = "";
    var failures = run.source_failures || [];
    banner.hidden = !(partial || failures.length);
    failures.forEach(function (f) {
      var li = el("li", null, [el("strong", { text: compName(f.competitor) }), ": "]);
      if (isHttp(f.url)) li.appendChild(el("a", { href: f.url, target: "_blank", rel: "noopener noreferrer", text: f.url }));
      else li.appendChild(document.createTextNode(f.url || "unknown source"));
      if (f.error) li.appendChild(document.createTextNode(" (" + f.error + ")"));
      list.appendChild(li);
    });
  }

  // ------------------------------------------------------------ filters

  function filterOptions(run) {
    var opts = {
      competitor: competitors.map(function (c) { return { value: c.id, label: c.display_name }; }),
      category: CATEGORIES.map(function (c) { return { value: c.id, label: c.label }; })
    };
    TAG_DIMS.forEach(function (dim) {
      var seen = {};
      (run.items || []).forEach(function (it) {
        ((it.tags && it.tags[dim.id]) || []).forEach(function (t) { seen[t] = true; });
      });
      // Keep active values visible even if this week has no such tag, so they can be cleared.
      state.filters[dim.id].forEach(function (t) { seen[t] = true; });
      opts[dim.id] = Object.keys(seen).sort(function (a, b) { return a.localeCompare(b); })
        .map(function (t) { return { value: t, label: t }; });
    });
    return opts;
  }

  function renderFilters(run) {
    var root = $("filter-groups");
    root.textContent = "";
    var opts = filterOptions(run);
    var groups = [{ id: "competitor", label: "Competitor" }, { id: "category", label: "Category" }].concat(TAG_DIMS);

    groups.forEach(function (g) {
      var chips = el("div", { className: "chips" });
      if (!opts[g.id].length) chips.appendChild(el("p", { className: "chip__none", text: "No " + g.label.toLowerCase() + " tags this week." }));
      opts[g.id].forEach(function (o) {
        var on = state.filters[g.id].indexOf(o.value) >= 0;
        var btn = el("button", { type: "button", className: "chip", "aria-pressed": on ? "true" : "false", text: o.label });
        btn.addEventListener("click", function () { toggle(g.id, o.value); });
        chips.appendChild(btn);
      });
      root.appendChild(el("fieldset", { className: "filter-group" }, [
        el("legend", { className: "label", text: g.label }),
        chips
      ]));
    });

    var n = activeCount();
    $("filter-count").textContent = n ? n + " active" : "";
    $("clear-filters").disabled = !n;
  }

  function toggle(dim, value) {
    var list = state.filters[dim];
    var i = list.indexOf(value);
    if (i >= 0) list.splice(i, 1); else list.push(value);
    update();
  }

  function clearFilters() {
    DIMS.forEach(function (d) { state.filters[d] = []; });
    update();
  }

  // ------------------------------------------------------------- items

  function renderItem(item, allRuns) {
    var comp = compById[item.competitor] || {};
    var flags = el("div", { className: "item__flags" });
    if (item.basis === "analysis") flags.appendChild(el("span", { className: "flag flag--analysis", text: "Analysis" }));
    if (item.fallback) flags.appendChild(el("span", { className: "flag", text: "Fallback" }));
    if (item.update_of) flags.appendChild(el("span", { className: "flag", text: "Update" }));
    if (sampleMode && item.sample) flags.appendChild(el("span", { className: "flag", text: "Sample" }));

    var meta = el("p", { className: "item__meta" });
    var who = el("strong", { text: compName(item.competitor) });
    meta.appendChild(who);
    if (item.category === "financial" && comp.parent_reporting && comp.parent_company) {
      meta.appendChild(el("span", { className: "parent-label", text: compName(item.competitor) + " → " + comp.parent_company + " (parent-level figures)" }));
      who.hidden = true;
    }
    var pub = primaryDate(item);
    if (pub) meta.appendChild(el("span", null, ["Published ", el("time", { datetime: pub, text: fmtDay(pub) })]));

    var children = [
      flags.childNodes.length ? flags : null,
      el("h3", { className: "item__title", text: item.title }),
      meta
    ];

    if (item.category === "event" && item.event) {
      var ev = item.event;
      var when = fmtDay(ev.start_date) + (ev.end_date && ev.end_date !== ev.start_date ? " to " + fmtDay(ev.end_date) : "");
      var evLine = el("p", { className: "item__event" }, [el("strong", { text: when })]);
      if (ev.location) evLine.appendChild(el("span", { text: ev.location }));
      if (ev.booth) evLine.appendChild(el("span", { text: "Booth " + ev.booth.replace(/^booth\s+/i, "") }));
      children.push(evLine);
    }

    children.push(el("p", { className: "item__summary", text: item.summary }));

    if (item.fallback) {
      children.push(el("p", { className: "item__note", text: "Fallback: the competitor's own channel was not usable for this item, so it is reported from the secondary source below." }));
    }
    if (item.update_of) {
      var original = null;
      allRuns.forEach(function (r) {
        (r.items || []).forEach(function (it) { if (it.id === item.update_of) original = { item: it, run: r }; });
      });
      children.push(el("p", { className: "item__note", text: original
        ? "Updates “" + original.item.title + "” from the week of " + fmtDay(original.run.run_date) + "."
        : "Updates an item from an earlier week." }));
    }

    var tagBits = [];
    TAG_DIMS.forEach(function (d) { ((item.tags && item.tags[d.id]) || []).forEach(function (t) { tagBits.push(t); }); });
    if (tagBits.length) children.push(el("p", { className: "item__tags" }, tagBits.map(function (t) { return el("span", { text: t }); })));

    var sources = el("ul", { className: "item__sources" });
    (item.sources || []).forEach(function (s) {
      if (!isHttp(s.url)) return;
      sources.appendChild(el("li", null, [el("a", {
        className: "source-link", href: s.url, target: "_blank", rel: "noopener noreferrer"
      }, ["Source: " + (s.publisher || s.url), svgIcon(["M7 7h10v10", "M7 17 17 7"]), el("span", { className: "visually-hidden", text: " (opens in a new tab)" })])]));
    });
    children.push(sources);

    return el("li", null, [el("article", { className: "item" }, children)]);
  }

  function emptyState(text, withClear) {
    var p = el("p", { className: "empty", text: text });
    if (withClear) {
      var b = el("button", { type: "button", className: "link-button", text: "Clear filters" });
      b.addEventListener("click", clearFilters);
      p.appendChild(b);
    }
    return p;
  }

  function sortByDateDesc(a, b) {
    var da = primaryDate(a), db = primaryDate(b);
    if (da !== db) return da < db ? 1 : -1;
    return a.title.localeCompare(b.title);
  }

  function renderSections(run) {
    var root = $("sections");
    root.textContent = "";
    var all = run.items || [];
    var filtering = activeCount() > 0;
    var today = todayStr();

    SECTIONS.forEach(function (sec) {
      var inCategory = all.filter(function (it) { return it.category === sec.id; });
      if (sec.id === "event") {
        inCategory = inCategory.filter(function (it) {
          var ev = it.event || {};
          var last = ev.end_date || ev.start_date || "";
          return last >= today;
        });
      }
      var shown = inCategory.filter(matches);

      if (sec.id === "event") {
        shown.sort(function (a, b) { return (a.event.start_date || "") < (b.event.start_date || "") ? -1 : 1; });
      } else {
        shown.sort(sortByDateDesc);
      }

      var head = el("header", { className: "section__head" }, [
        el("h2", { className: "section__title", id: "sec-" + sec.id }, [
          sec.label,
          el("span", { className: "section__count", text: shown.length + (shown.length === 1 ? " item" : " items") })
        ]),
        el("p", { className: "section__lede", text: sec.lede })
      ]);
      var body;

      if (!shown.length) {
        if (filtering && inCategory.length) body = emptyState("No items match the current filters.", true);
        else if (sec.id === "financial") body = emptyState("No public financial disclosure this period.", false);
        else if (sec.id === "event") body = emptyState("No upcoming events reported.", false);
        else body = emptyState("Nothing reported this period.", false);
      } else if (sec.id === "new_product") {
        body = el("div");
        competitors.forEach(function (c) {
          var mine = shown.filter(function (it) { return it.competitor === c.id; });
          if (!mine.length) return;
          body.appendChild(el("div", { className: "group" }, [
            el("h3", { className: "group__title label", text: c.display_name }),
            el("ul", { className: "items" }, mine.map(function (it) { return renderItem(it, runs); }))
          ]));
        });
      } else {
        body = el("ul", { className: "items" }, shown.map(function (it) { return renderItem(it, runs); }));
      }

      root.appendChild(el("section", { className: "section", "aria-labelledby": "sec-" + sec.id }, [head, body]));
    });
  }

  // ------------------------------------------------------------- render

  function update() {
    writeUrl();
    var run = currentRun();
    renderHeader(run);
    renderFilters(run);
    renderSections(run);
  }

  function init() {
    var year = $("year");
    if (year) year.textContent = String(new Date().getFullYear());

    $("sample-notice").hidden = !sampleMode;

    if (!runs.length) {
      // Empty state: no published runs (or no sample runs).
      $("empty-digest").hidden = false;
      if (sampleMode) {
        $("empty-digest").querySelector(".section__title").textContent = "No sample data found.";
        $("empty-digest").querySelector(".cta").hidden = true;
      }
      return;
    }

    var filters = $("filters");
    filters.hidden = false;
    if (activeCount() || (window.matchMedia && window.matchMedia("(min-width: 48rem)").matches)) filters.open = true;

    $("week-select").addEventListener("change", function (e) {
      state.week = e.target.value;
      update();
    });
    $("clear-filters").addEventListener("click", clearFilters);

    update();
  }

  init();
})();
